  String guideLabel(Channel c){EpgProgram p=currentProgram(c);List<EpgProgram> next=nextPrograms(c,1);String now=p==null?"Ahora · Sin programación":"Ahora · "+timeRange(p)+" · "+p.title;String nx=next.isEmpty()?"":"\nSigue · "+timeRange(next.get(0))+" · "+next.get(0).title;return healthIcon(c)+" "+c.name+"\n"+now+nx;}
  void showGuideDetails(Channel c){EpgProgram now=currentProgram(c);List<EpgProgram> next=nextPrograms(c,5);StringBuilder m=new StringBuilder();m.append(healthText(c)).append("\n").append(c.group).append("\n\n");if(now!=null){m.append("AHORA  ").append(timeRange(now)).append("\n").append(now.title);if(!now.desc.isEmpty())m.append("\n").append(now.desc);m.append("\n\n");}else m.append("Sin programación actual disponible.\n\n");if(!next.isEmpty()){m.append("PRÓXIMAMENTE\n");for(EpgProgram p:next)m.append(formatTime(p.start)).append("  ").append(p.title).append("\n");}new AlertDialog.Builder(this).setTitle(c.name).setMessage(m.toString()).setNegativeButton("Cerrar",null).setPositiveButton("Ver ahora",(d,w)->{showHome();play(c);}).show();}
  void showGuideSettings(){clearContent();LinearLayout page=pageBase("Guía TV / EPG","Fuente de programación compatible con XMLTV");String detected=detectedEpgUrl.isEmpty()?"No detectada":"Detectada en la lista M3U";Button auto=menuCard("▤  Guía automática de la lista",detected,CARD),local=menuCard("▣  Abrir XMLTV local","Archivos .xml o .xml.gz",CARD),url=menuCard("↗  URL XMLTV","Configurar una fuente manual",CARD),refresh=menuCard("↻  Actualizar guía","Fuente actual: "+epgSourceLabel,BLUE);for(Button b:new Button[]{auto,local,url,refresh}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(62));p.setMargins(0,dp(5),0,0);page.addView(b,p);}auto.setOnClickListener(v->{getSharedPreferences("tvplus",MODE_PRIVATE).edit().remove("epg_uri").remove("epg_url").apply();loadGuideAuto();showGuide();});local.setOnClickListener(v->pickEpg());url.setOnClickListener(v->askEpgUrl());refresh.setOnClickListener(v->{reloadGuide();showGuide();});}
  void reloadGuide(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);String uri=p.getString("epg_uri",""),url=p.getString("epg_url","");if(!uri.isEmpty())loadEpgFromUri(Uri.parse(uri),"XMLTV local");else if(!url.isEmpty())loadEpgFromUrl(url,"XMLTV manual");else if(!detectedEpgUrl.isEmpty())loadEpgFromUrl(detectedEpgUrl,"Guía automática");else toast("Esta lista no incluye una fuente EPG. Configúrala en Fuente EPG.");}
  void pickEpg(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,OPEN_EPG);}
  void askEpgUrl(){final EditText e=new EditText(this);e.setHint("https://servidor/guide.xml o .xml.gz");e.setSingleLine(true);new AlertDialog.Builder(this).setTitle("URL XMLTV").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{String u=e.getText().toString().trim();if(u.startsWith("http://")||u.startsWith("https://")){getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString("epg_url",u).remove("epg_uri").apply();loadEpgFromUrl(u,"XMLTV manual");showGuide();}else toast("Ingrese una URL válida");}).show();}

  void showSavedPage(String label,boolean fav){clearContent();setNavActive(fav?"fav":"recent");LinearLayout page=pageBase(label,fav?"Tus canales guardados":"Últimos canales vistos");List<Channel> data=new ArrayList<>();if(fav){for(Channel c:all)if(favorites.contains(c.id))data.add(c);}else{for(String id:recents)for(Channel c:all)if(c.id.equals(id)){data.add(c);break;}}addChannelRows(page,data);}
  void showCategories(){clearContent();setNavActive("cat");LinearLayout page=pageBase("Categorías","Todo el contenido, organizado para encontrarlo rápido");String[] cats={"⚽ Deportes","🎬 Películas","📺 Series","📰 Noticias","🙏 Religión","👧 Infantil","🎵 Música","🌎 Documentales"};int[] colors={CARD,CARD,CARD,CARD,CARD,CARD,CARD,CARD};GridLayout grid=new GridLayout(this);grid.setColumnCount(getResources().getConfiguration().screenWidthDp>=600?4:2);page.addView(grid,new LinearLayout.LayoutParams(-1,-2));for(int i=0;i<cats.length;i++){final String raw=cats[i];final String c=raw.substring(raw.indexOf(' ')+1).replace("Infantil","Niños");int n=0;for(Channel ch:all)if(categoryMatch(ch,c))n++;Button b=actionBtn(raw+"\n"+n+" canales",colors[i]);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setTextSize(13);GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=0;gp.height=dp(86);gp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);gp.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(b,gp);b.setOnClickListener(v->showCategoryChannels(c));}}
